import {operationTypes,operatingSchedule,buildOperations,validateReview,operationDigest,beijingDay,checklistKey} from './data/operations.js';
import {makeRadarDraft} from './radar.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={pending:'待核验',reviewing:'核验中',reviewed:'已核验（本机记录）',done:'已处理（本机记录）',ignored:'已忽略'};
const key='vibebase-operations-v1';
function load(){try{const d=JSON.parse(localStorage.getItem(key)||'{}');return {reviews:d.reviews||{},checklist:d.checklist||{}};}catch{return {reviews:{},checklist:{}};}}
export function operationsPage(){return `<div class="page" id="operationsRoot"><div class="discovery-heading"><span class="eyebrow">VIBEBASE OPERATIONS</span><h1>把信息变成下一步行动。</h1><p>从每日线索到核验、选题与更新记录。规则建议不等于事实结论。</p></div><div class="radar-toolbar"><a class="tool-link" href="#radar" data-route="radar">AI 动态 →</a><a class="tool-link" href="#radar/sources" data-route="radar/sources">采集状态 →</a><button class="soft-btn" id="opsRefresh">刷新线索</button><button class="soft-btn" id="opsExport">导出运营日报</button></div><p class="notice">处理进度、依据和备注只保存在当前浏览器，不是共享后台。保存记录不会自动修改模型、价格、榜单或发布文章；清理浏览器数据会丢失记录。</p><p id="opsStatus" role="status">正在读取真实采集记录…</p><div class="stat-strip" id="opsStats"></div><section class="section"><div class="section-head"><div><h2>今日运营节奏</h2><p>北京时间 · 手动待办，不会自动发送提醒或执行更新。</p></div></div><div class="discovery-grid two">${operatingSchedule.map(([id,time,text])=>`<label class="discovery-card"><input type="checkbox" data-ops-check="${id}"> <strong>${time}</strong><p>${text}</p></label>`).join('')}</div></section><section class="section"><h2>待核验与处理队列</h2><div class="radar-toolbar"><label>信息类型<select id="opsType"><option value="all">全部类型</option>${operationTypes.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</select></label><label>处理状态<select id="opsFilter"><option value="open">待处理</option><option value="all">全部状态</option>${Object.entries(labels).map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></label><label>时间范围<select id="opsWindow"><option value="day">过去 24 小时</option><option value="all">近 30 天</option></select></label></div><div class="discovery-grid two" id="opsQueue"></div></section><section class="section"><h2>CoVibe 选题机会</h2><p>从当前时间范围的线索中选出最多 3 条不同原帖；仅生成可编辑提纲，不编造使用步骤和实测结果。</p><div id="opsTopics" class="discovery-grid three"></div></section><section class="section"><h2>需求与改进方向</h2><p>按规则统计线索中的主题频次，不是用户数量、独立证据数或全站访问量。</p><div id="opsDemand" class="radar-home-strip"></div></section><section id="opsEditor" class="radar-draft" hidden><h2>记录处理结果</h2><form id="opsForm"><div class="radar-toolbar"><label>状态<select name="status">${Object.entries(labels).map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></label><label>人工核对的依据类型<select name="evidence"><option value="community">社区经验 / 待确认</option><option value="official">官方文档或公告</option><option value="channel">站方声明</option><option value="reproduced">本人已复现</option></select></label></div><label>依据链接<input name="url" type="url" maxlength="1000" placeholder="https://…"></label><label>实际复现日期（选择本人已复现时必填）<input name="testedAt" type="date" max="${beijingDay()}"></label><label>核验结论 / 实际修改 / 适用范围<textarea name="note" maxlength="2000" rows="5"></textarea></label><div class="radar-toolbar"><button class="soft-btn" type="submit">保存到当前浏览器</button><button class="soft-btn" id="opsCancel" type="button">关闭</button></div><p id="opsSaveStatus" role="status"></p></form></section><section id="opsDraft" class="radar-draft" hidden><h2>CoVibe 工作提纲</h2><textarea id="opsDraftText" rows="16" aria-label="CoVibe 可编辑提纲"></textarea><button class="soft-btn" id="opsDownloadDraft">下载 Markdown</button></section></div>`;}
function download(text,name){const u=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
export function bindOperations(){
 const root=document.querySelector('#operationsRoot');if(!root)return;
 let tasks=[],data=load(),active=null,loaded=false;
 const get=id=>root.querySelector('#'+id),scope=()=>tasks.filter(t=>get('opsWindow').value==='all'||t.recent);
 function save(next){localStorage.setItem(key,JSON.stringify(next));data=next;}
 function draw(){
  const rows=scope(),status=t=>data.reviews[t.id]?.status||'pending',open=t=>!['done','ignored'].includes(status(t));
  get('opsStats').innerHTML=[['原帖',new Set(rows.map(t=>t.post.id)).size],['待处理动作',rows.filter(open).length],['优先处理 P0',rows.filter(t=>t.priority===0&&open(t)).length],['本机已处理',rows.filter(t=>status(t)==='done').length]].map(([name,n])=>`<div class="stat"><strong>${n}</strong><span>${name}</span></div>`).join('');
  const type=get('opsType').value,filter=get('opsFilter').value;
  const queue=rows.filter(t=>(type==='all'||t.type.id===type)&&(filter==='all'||(filter==='open'?open(t):status(t)===filter)));
  get('opsQueue').innerHTML=queue.length?queue.map(t=>`<article class="discovery-card"><span class="tag">P${t.priority} · ${t.type.name}</span><h3>${esc(t.type.action)}</h3><p>${esc(t.post.text.slice(0,260))}</p><p class="mini-meta">规则识别，待人工核验 · @${esc(t.post.author)} · ${esc(t.post.publishedAt.slice(0,10))}</p><p><strong>应核对：</strong>${esc(t.type.fields)}</p><p>${labels[status(t)]||labels.pending}</p><div class="discovery-card-foot"><a href="${esc(t.post.url)}" target="_blank" rel="noopener noreferrer">原帖 ↗</a> · <a href="#${t.type.route}" data-route="${t.type.route}">打开对应页面 →</a><button class="small-action" data-ops-edit="${esc(t.id)}">记录处理结果</button></div></article>`).join(''):`<p class="empty">${tasks.length?'当前筛选没有待办。':'暂无真实线索。配置采集来源后自动生成待核验任务，不填充演示事项。'}</p>`;
  const chosen=new Map();for(const t of rows.filter(t=>open(t)&&['tutorial','free','migration','release','price','demand'].includes(t.type.id))){if(chosen.size>=3)break;if(!chosen.has(t.post.id))chosen.set(t.post.id,t);}
  get('opsTopics').innerHTML=[...chosen.values()].map(t=>`<article class="discovery-card"><span class="tag">${t.type.name}</span><h3>${esc(t.post.text.slice(0,90))}</h3><p>补齐：${esc(t.type.fields)}</p><button class="small-action" data-ops-draft="${esc(t.id)}">生成带来源的提纲</button></article>`).join('')||'<p class="empty">暂无可用选题，等待有证据的新信息。</p>';
  get('opsDemand').innerHTML=operationTypes.map(type=>`<span>${type.name}：${new Set(rows.filter(t=>t.type.id===type.id).map(t=>t.post.id)).size} 条</span>`).join('');
  root.querySelectorAll('[data-ops-check]').forEach(el=>{el.checked=Boolean(data.checklist[checklistKey(el.dataset.opsCheck)]);});
 }
 async function refresh(){get('opsRefresh').disabled=true;try{const r=await fetch('/api/radar');const d=await r.json();if(!r.ok)throw Error();if(!root.isConnected)return;tasks=buildOperations(d.items);loaded=true;get('opsStatus').textContent=d.collection.message+'。任务由当前真实线索生成，采集频率沿用现有配置。';draw();}catch{if(root.isConnected)get('opsStatus').textContent='读取失败，未取得新线索；已有列表保留。';}finally{get('opsRefresh').disabled=false;}}
 root.querySelectorAll('#opsType,#opsFilter,#opsWindow').forEach(el=>el.onchange=draw);get('opsRefresh').onclick=refresh;
 root.addEventListener('change',e=>{if(!e.target.matches('[data-ops-check]'))return;try{save({...data,checklist:{...data.checklist,[checklistKey(e.target.dataset.opsCheck)]:e.target.checked}});}catch{e.target.checked=!e.target.checked;get('opsStatus').textContent='浏览器存储不可用，待办状态未保存。';}});
 root.addEventListener('click',e=>{const edit=e.target.closest('[data-ops-edit]'),draft=e.target.closest('[data-ops-draft]');if(edit){active=tasks.find(t=>t.id===edit.dataset.opsEdit);if(!active)return;const v=data.reviews[active.id]||{status:'pending',evidence:'community',url:'',testedAt:'',note:''};for(const name of ['status','evidence','url','testedAt','note'])get('opsForm').elements[name].value=v[name]||'';get('opsEditor').hidden=false;get('opsSaveStatus').textContent='当前任务：'+active.type.name;get('opsEditor').scrollIntoView({behavior:'smooth'});}if(draft){const t=tasks.find(t=>t.id===draft.dataset.opsDraft);if(!t)return;get('opsDraftText').value=makeRadarDraft(t.post)+'\n## 本次运营核验重点\n'+t.type.fields+'\n';get('opsDraft').hidden=false;get('opsDraft').scrollIntoView({behavior:'smooth'});}});
 get('opsForm').onsubmit=e=>{e.preventDefault();if(!active)return;try{const review=validateReview(Object.fromEntries(new FormData(e.target)));save({...data,reviews:{...data.reviews,[active.id]:review}});get('opsSaveStatus').textContent='已保存到本机；网站内容未自动更改。';draw();}catch(error){get('opsSaveStatus').textContent=error.message;}};
 get('opsCancel').onclick=()=>get('opsEditor').hidden=true;
 get('opsExport').onclick=()=>{if(!loaded){get('opsStatus').textContent='请先成功读取线索再导出日报。';return;}download(operationDigest(tasks,data.reviews),'vibebase-operations-'+beijingDay()+'.md');};get('opsDownloadDraft').onclick=()=>download(get('opsDraftText').value,'covibe-operations-draft.md');draw();refresh();
}
